<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessageBox, ElMessage } from 'element-plus'
import { post, request } from '../api/client'
import { listMediaUsers, listNativeLibraries, type MediaUser, type MediaLibrary } from '../api/mediaServer'
const users=ref<MediaUser[]>([]), libraries=ref<MediaLibrary[]>([])
const busy=ref(false), saving=ref(false), error=ref(''), formError=ref(''), dialog=ref(false), resetDialog=ref(false), selected=ref<MediaUser>()
const resetPassword=ref(''), resetConfirm=ref('')
const form=reactive({id:'',username:'',displayName:'',password:'',confirm:'',enabled:true,revision:0,allowed:[] as string[],play:[] as string[]})
const enabledCount=computed(()=>users.value.filter(u=>u.enabled).length)
async function load(){busy.value=true;error.value='';try{[users.value,libraries.value]=await Promise.all([listMediaUsers(),listNativeLibraries()])}catch(e){error.value=e instanceof Error?e.message:'媒体用户读取失败'}finally{busy.value=false}}
function edit(user?:MediaUser){formError.value='';Object.assign(form,{id:user?.id||'',username:user?.username||'',displayName:user?.displayName||'',password:'',confirm:'',enabled:user?.enabled??true,revision:user?.revision||0,allowed:user?.grants.map(g=>g.libraryId)||[],play:user?.grants.filter(g=>g.canPlay).map(g=>g.libraryId)||[]});dialog.value=true}
function passwordValid(password:string){return [...password].length>=6&&[...password].length<=20}
async function save(){
 if(!form.id&&(!passwordValid(form.password)||form.password!==form.confirm)){formError.value='密码需6–20个字符，且两次输入一致';return}
 saving.value=true;formError.value=''
 try{const body={username:form.username,displayName:form.displayName,enabled:form.enabled,revision:form.revision,grants:form.allowed.map(libraryId=>({libraryId,canPlay:form.play.includes(libraryId)})),...(form.id?{}:{password:form.password})};await request(`/media-server/users${form.id?'/'+form.id:''}`,{method:form.id?'PUT':'POST',body:JSON.stringify(body)});dialog.value=false;form.password='';form.confirm='';ElMessage.success(form.id?'用户已更新，旧会话已撤销':'媒体用户已创建，首次登录需修改密码');await load()}catch(e){formError.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}
}
function openReset(u:MediaUser){selected.value=u;resetPassword.value='';resetConfirm.value='';formError.value='';resetDialog.value=true}
async function reset(){if(!selected.value)return;if(!passwordValid(resetPassword.value)||resetPassword.value!==resetConfirm.value){formError.value='密码需6–20个字符，且两次输入一致';return}saving.value=true;formError.value='';try{await post(`/media-server/users/${selected.value.id}/password`,{revision:selected.value.revision,password:resetPassword.value});resetDialog.value=false;resetPassword.value='';resetConfirm.value='';ElMessage.success('密码已重置，旧会话已撤销；下次登录需改密码');await load()}catch(e){formError.value=e instanceof Error?e.message:'重置失败'}finally{saving.value=false}}
async function mutate(u:MediaUser,remove=false){try{await ElMessageBox.confirm(remove?`删除媒体用户 ${u.username} 及其权限和会话？不会删除媒体文件。`:`撤销 ${u.username} 的全部媒体会话？`,remove?'删除媒体用户':'撤销媒体会话',{type:'warning',confirmButtonText:'确认',cancelButtonText:'取消'});await request(`/media-server/users/${u.id}${remove?'':'/sessions/revoke'}`,{method:remove?'DELETE':'POST',body:JSON.stringify({revision:u.revision})});ElMessage.success(remove?'媒体用户已删除':'会话已撤销');await load()}catch(e){if(e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'操作失败'}}
onMounted(load)
</script>
<template>
 <section class="page-heading"><div><span class="page-kicker">MEDIA / 独立身份</span><h1>媒体用户</h1><p>仅用于内置媒体库，不关联管理员账号或 Emby 用户；公开注册关闭。</p></div><el-button type="primary" @click="edit()">添加媒体用户</el-button></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <section class="panel"><div class="user-toolbar"><p>已添加 {{users.length}} 位 · 启用 {{enabledCount}} 位</p><div><RouterLink to="/media-server">查看内置服务能力</RouterLink><el-button :loading="busy" @click="load">刷新</el-button></div></div>
 <div class="user-table" v-loading="busy"><el-table :data="users" empty-text="尚未创建媒体用户" :min-height="180"><el-table-column label="账号" min-width="170"><template #default="{row}"><strong>{{row.username}}</strong><p class="field-hint">{{row.displayName}}</p></template></el-table-column><el-table-column label="状态" min-width="145"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'禁用'}}</el-tag><p v-if="row.mustChangePassword" class="field-hint">登录后需改密码</p></template></el-table-column><el-table-column label="媒体库权限" min-width="200"><template #default="{row}"><span v-if="!row.grants.length" class="field-hint">无权限</span><div v-for="grant in row.grants" :key="grant.libraryId">{{libraries.find(l=>l.id===grant.libraryId)?.name||grant.libraryId}} · {{grant.canPlay?'浏览 + 预留播放':'仅浏览'}}</div></template></el-table-column><el-table-column prop="activeSessions" label="有效会话" width="100"/><el-table-column label="操作" min-width="250"><template #default="{row}"><div class="user-actions"><el-button @click="edit(row)">编辑</el-button><el-button @click="openReset(row)">重置密码</el-button><el-button @click="mutate(row)">撤销会话</el-button><el-button type="danger" plain @click="mutate(row,true)">删除</el-button></div></template></el-table-column></el-table></div>
 <p class="field-hint">密码仅设置时输入，不保存明文、不回显哈希。修改用户或权限会撤销旧会话。播放权限是后续票据接口的授权预留，当前无法通过内置媒体库播放。</p></section>
 <el-dialog v-model="dialog" :title="form.id?'编辑媒体用户':'添加媒体用户'" width="min(600px,94vw)" @closed="form.password='';form.confirm=''">
 <el-alert v-if="formError" :title="formError" type="error" :closable="false"/>
 <el-form label-position="top" class="media-user-form" @submit.prevent="save"><el-form-item label="媒体账号" for="media-username"><el-input id="media-username" v-model="form.username" autocomplete="off" maxlength="32" placeholder="3–32位字母、数字、下划线、短横线或点"/></el-form-item><el-form-item label="显示名称" for="media-display"><el-input id="media-display" v-model="form.displayName" maxlength="80" placeholder="不填写时使用媒体账号"/></el-form-item><template v-if="!form.id"><el-form-item label="初始密码" for="media-password"><el-input id="media-password" v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认初始密码" for="media-confirm"><el-input id="media-confirm" v-model="form.confirm" type="password" show-password autocomplete="new-password"/></el-form-item><p class="field-hint">密码6–20个字符，首次登录必须修改。</p></template>
 <el-form-item label="账号启用"><el-switch v-model="form.enabled" aria-label="启用媒体账号"/></el-form-item><fieldset><legend>可浏览的媒体库</legend><el-checkbox-group v-model="form.allowed"><el-checkbox v-for="library in libraries" :key="library.id" :value="library.id">{{library.name}}</el-checkbox></el-checkbox-group><p class="field-hint">默认无权限；不会自动授予后续新增媒体库。</p></fieldset><fieldset><legend>预留播放权限</legend><el-checkbox-group v-model="form.play"><el-checkbox v-for="library in libraries" :key="library.id" :value="library.id" :disabled="!form.allowed.includes(library.id)">{{library.name}}播放</el-checkbox></el-checkbox-group><p class="field-hint">当前只读目录，不签发播放票据。</p></fieldset></el-form>
 <template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{form.id?'保存用户':'创建用户'}}</el-button></template></el-dialog>
 <el-dialog v-model="resetDialog" title="重置媒体用户密码" width="min(520px,94vw)" @closed="resetPassword='';resetConfirm=''">
 <p>为 {{selected?.username}} 设置新初始密码，撤销所有会话并要求下次登录修改。</p><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="新的初始密码" for="media-reset"><el-input id="media-reset" v-model="resetPassword" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新初始密码" for="media-reset-confirm"><el-input id="media-reset-confirm" v-model="resetConfirm" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="resetDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="reset">重置密码</el-button></template></el-dialog>
</template>
<style scoped>
.user-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:16px}.user-toolbar p{color:var(--muted)}.user-toolbar>div{display:flex;align-items:center;gap:16px}.user-toolbar a{color:var(--el-color-primary)}.user-table{overflow:auto}.user-table .el-table{min-width:780px}.user-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.user-actions .el-button{margin:0;min-height:36px}.media-user-form fieldset{border:1px solid var(--border);border-radius:8px;padding:16px;margin:16px 0}.media-user-form legend{padding:0 8px;font-size:14px}@media(max-width:600px){.user-toolbar,.user-toolbar>div{align-items:flex-start;flex-wrap:wrap}.user-actions .el-button{min-height:44px}}
</style>
